// All human-readable documents are generated here. The output depends only on dag + ledger (not the current time),
// so "regenerate == file on disk" can serve as a gate: a mismatch means someone hand-edited a generated file.
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { capabilityOf, contractMajor } from './dag.mjs';
import { openDecisions, pendingE2e } from './state.mjs';
import { atomicWrite, stableJson } from './util.mjs';

const HEADER = (seq) => `<!-- GENERATED by \`dlm render\` from ledger seq ${seq}. 不要手改:改 dag.json 或透過 dlm 寫事件。 -->`;

export function describe(ev) {
  switch (ev.type) {
    case 'dispatch': return `派工 ${ev.dispatch_id} → ${ev.node_id} [${ev.leg}] 第 ${ev.attempt} 次`;
    case 'worker_done': return `交件 ${ev.dispatch_id} @${ev.commit.slice(0, 7)}`;
    case 'worker_blocked': return `卡住 ${ev.dispatch_id}:${ev.reason}`;
    case 'worker_failed': return `失敗 ${ev.dispatch_id}:${ev.reason}`;
    case 'verify': {
      const f = ev.results.filter((r) => r.outcome === 'FAIL').length;
      const a = ev.results.filter((r) => r.outcome === 'ABSTAIN').length;
      return `驗證 ${ev.dispatch_id}:FAIL ${f} / ABSTAIN ${a} / 共 ${ev.results.length}`;
    }
    case 'gates': return `全 gate ${ev.dispatch_id}:${ev.ok ? '綠' : '紅'}`;
    case 'critic': return `Critic ${ev.ref}:${ev.verdict}`;
    case 'reject': return `退回 ${ev.node_id}:${ev.reason}`;
    case 'leg_done': return `${ev.node_id} 完成 ${ev.leg} 棒`;
    case 'accept': return `合併 ${ev.node_id} @${ev.merge_sha.slice(0, 7)}`;
    case 'block': return `封鎖 ${ev.node_id}:${ev.reason}`;
    case 'unblock': return `解除 ${ev.node_id}(${ev.ref})`;
    case 'decision_request': return `請求決定 ${ev.ref}:${ev.question}`;
    case 'decision': return `決定 ${ev.ref} = ${ev.choice}${ev.delegated ? '(代行)' : ''}`;
    case 'e2e_request': return `請使用者試用 ${ev.node_id}`;
    case 'e2e_confirm': return `使用者試用 ${ev.node_id}:${ev.ok ? '通過' : '不通過'}`;
    case 'node_added': return `新增節點 ${ev.node_id}(批准:${ev.approved_by})`;
    case 'node_imported': return `匯入節點 ${ev.node_id} = ${ev.status}`;
    case 'contract_bump': return `契約 @${ev.from} → @${ev.to},需重驗 ${ev.stale.length} 個`;
    case 'halt': return `停機:${ev.reason}`;
    case 'resume': return '恢復';
    case 'cost': return `花費 ${ev.dispatch_id} $${ev.usd.toFixed(2)}`;
    case 'note': return `備註:${ev.text}`;
    default: return ev.type;
  }
}

export function renderStatus(root, dag, state, events) {
  const lines = [HEADER(state.maxSeq), '', '# 進度', ''];
  const done = [...state.nodes.values()].filter((n) => n.status === 'done').length;
  lines.push(`契約 @${contractMajor(root)} · 節點 ${dag.nodes.length} · 完成 ${done}${state.halted ? ` · **停機中:${state.halted.reason}**` : ''}`, '');
  lines.push('| 節點 | 類型 | 標題 | 狀態 | 已完成棒 | 依賴 |', '|---|---|---|---|---|---|');
  for (const n of dag.nodes) {
    const s = state.nodes.get(n.id);
    const status = s.status + (s.reason ? `(${s.reason})` : '') + (s.e2e && !s.e2e.confirm ? ' · 待試用' : '');
    lines.push(`| \`${n.id}\` | ${n.kind} | ${n.title} | ${status} | ${s.legsDone.join(', ') || '—'} | ${(n.depends_on ?? []).join(', ') || '—'} |`);
  }
  const decisions = openDecisions(state);
  const e2e = pendingE2e(state);
  lines.push('', '## 等使用者', '');
  if (!decisions.length && !e2e.length) lines.push('(無)');
  for (const d of decisions) lines.push(`- \`${d.ref}\` ${d.question}`);
  for (const n of e2e) lines.push(`- 試用 \`${n.id}\`:${n.e2e.scenarios.map((s) => `${s.file}:${s.line}`).join(', ')}`);
  lines.push('', '## 最近 20 個事件', '');
  for (const ev of events.filter((e) => e.type !== 'inbox_viewed').slice(-20)) lines.push(`- #${ev.seq} ${ev.ts.slice(0, 16).replace('T', ' ')} ${ev.actor}:${describe(ev)}`);
  return `${lines.join('\n')}\n`;
}

export function renderDecisions(state) {
  const lines = [HEADER(state.maxSeq), '', '# 決定', '', '## 待決', ''];
  const open = openDecisions(state);
  if (!open.length) lines.push('(無)');
  for (const r of open) {
    lines.push(`### \`${r.ref}\``, '', r.question, '');
    for (const o of r.options) lines.push(`- **${o.key}**:${o.label}`);
    if (r.recommendation) lines.push('', `建議:${r.recommendation}${r.reason ? `——${r.reason}` : ''}`);
    lines.push('');
  }
  lines.push('## 已決', '', '| ref | 選擇 | 誰 | 原話 | seq |', '|---|---|---|---|---|');
  for (const rec of state.decisions.values()) {
    if (!rec.answer) continue;
    const a = rec.answer;
    lines.push(`| \`${a.ref}\` | ${a.choice} | ${a.actor}${a.delegated ? '(代行)' : ''} | ${a.verbatim.replace(/\|/g, '\\|').replace(/\n/g, ' ')} | ${a.seq} |`);
  }
  return `${lines.join('\n')}\n`;
}

export function renderStandalone(dag) {
  const out = {};
  for (const n of dag.nodes) {
    if (!n.standalone) continue;
    out[capabilityOf(n.id)] = { cmd: n.standalone, interactive: false, expect: 'exit 0', cleanup: [] };
  }
  return stableJson(out);
}

export function renderAll(root, dag, state, events) {
  return {
    'STATUS.md': renderStatus(root, dag, state, events),
    'DECISIONS.md': renderDecisions(state),
    'standalone.json': renderStandalone(dag),
  };
}

export function writeRendered(root, files) {
  for (const [name, text] of Object.entries(files)) {
    const p = join(root, name);
    if (!existsSync(p) || readFileSync(p, 'utf8') !== text) atomicWrite(p, text);
  }
}

export function renderDrift(root, files) {
  return Object.entries(files)
    .filter(([name, text]) => !existsSync(join(root, name)) || readFileSync(join(root, name), 'utf8') !== text)
    .map(([name]) => name);
}
